use kimo_core::render::Frames;
#[test]fn float_cache_quantizes_only_on_request(){let f=Frames{still:false,working_linear:false,quantized:Default::default(),linear_buf:Some(vec![0.2,0.4,0.6,1.]),buf:vec![],fs:4,first:0};assert_eq!(f.len(),1);assert!(f.quantized.get().is_none());assert_eq!(f.get_float(0).unwrap()[0],0.2);assert!(f.quantized.get().is_none());assert_eq!(f.get(0).unwrap(),&[51,102,153,255]);assert!(f.quantized.get().is_some());}
#[test]fn source_windows_share_only_matching_identity(){use kimo_core::{commands::{Session,dispatch},render};use serde_json::json;let path=std::env::temp_dir().join(format!("kimo-cache-share-{}.png",std::process::id()));let mut cmd=std::process::Command::new("ffmpeg");assert!(cmd.args(["-v","error","-y","-f","lavfi","-i","color=c=red:s=32x32","-frames:v","1",path.to_str().unwrap()]).status().unwrap().success());let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let mut ids=vec![];for _ in 0..4{let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();ids.push(dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string());}render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();let p=s.cache.frames_of(&ids[0]).unwrap() as *const _;for id in &ids[1..]{assert_eq!(s.cache.frames_of(id).unwrap() as *const _,p)}dispatch(&mut s,"set_property",&json!({"clip_id":ids[3],"property":"fit","value":2})).unwrap();render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();assert_ne!(s.cache.frames_of(&ids[3]).unwrap() as *const _,p);std::fs::remove_file(path).unwrap();}
#[test]fn nested_export_reduces_cache_batch(){use kimo_core::{commands::{Session,dispatch},render};use serde_json::json;let dir=std::env::temp_dir();let path=dir.join(format!("kimo-batch-src-{}.mp4",std::process::id()));let out=dir.join(format!("kimo-batch-out-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","color=c=red:s=1280x720:r=25:d=0.4","-c:v","libx264",path.to_str().unwrap()]).status().unwrap().success());let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":1280,"height":720,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let mut ids=vec![];for i in 0..4{let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();ids.push(dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"duration":0.4,"in_point":i as f64*0.001})).unwrap()["clip_id"].clone());}let g=dispatch(&mut s,"group_clips",&json!({"clip_ids":ids})).unwrap()["clip_id"].clone();dispatch(&mut s,"group_clips",&json!({"clip_ids":[g]})).unwrap();assert!(render::export(&s.project,out.to_str().unwrap(),23).is_ok());std::fs::remove_file(path).unwrap();std::fs::remove_file(out).unwrap();}

#[test]fn one_frame_video_window_not_still(){let mut f=Frames{still:false,working_linear:false,quantized:Default::default(),linear_buf:None,buf:vec![0;4],fs:4,first:0};assert!(f.covers(0,0));assert!(!f.covers(1,1));assert!(!f.covers(0,100));f.still=true;assert!(f.covers(100,100));}
#[test]fn fractional_instant_cache_uses_floor_frame(){use kimo_core::{commands::{Session,dispatch},render};use serde_json::json;let path=std::env::temp_dir().join(format!("kimo-instant-src-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","color=c=red:s=32x32:r=25:d=0.1","-c:v","libx264",path.to_str().unwrap()]).status().unwrap().success());let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"duration":0.1})).unwrap()["clip_id"].clone();render::prepare_at(&s.project,&mut s.cache,Some(0.001)).unwrap();assert!(s.cache.frames_of(c.as_str().unwrap()).unwrap().covers(0,0));std::fs::remove_file(path).unwrap();}
